const b = $json.body;
const c = b.corpo || {};
const corretor = b.corretor || {};

// Os valores que chegam aqui (totalVida, vitalicia, temporaria, pensaoMensal, e o `valor` de cada
// categoria) já vêm formatados como texto pelo app (ex.: "R$ 1.043.500") — ver `apresentacao.ts`,
// função `construirApresentacao`. Não são números: não dá pra somar nem reformatar aqui, é só
// usar direto como string.
const fmt = (v) => (v === undefined || v === null || v === '') ? '—' : String(v);
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const MARINHO = '#0f3d63';
const FUNDO = '#f3f6fa';
const BORDA = '#dee7ef';
const TEXTO = '#1a2733';
const TEXTO_SEC = '#5b6b7a';

const linhaResumo = (rotulo, valor) => `
  <tr>
    <td style="padding:10px 0;border-bottom:1px solid ${BORDA};font:400 13px/1.4 Arial, sans-serif;color:${TEXTO_SEC};">${esc(rotulo)}</td>
    <td style="padding:10px 0;border-bottom:1px solid ${BORDA};font:700 13px/1.4 Arial, sans-serif;color:${MARINHO};text-align:right;">${esc(valor)}</td>
  </tr>`;

const linhasResumo = [
  linhaResumo('Proteção vitalícia', fmt(c.vitalicia)),
  linhaResumo('Proteção temporária', fmt(c.temporaria)),
  ...(c.pensaoMensal ? [linhaResumo('Pensão de Criação (mensal)', fmt(c.pensaoMensal) + '/mês')] : []),
].join('');

const linhaCategoria = (cat) => `
  <tr>
    <td style="padding:9px 0;">
      <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;">
        <tr>
          <td style="width:10px;">
            <div style="width:8px;height:8px;border-radius:50%;background:${esc(cat.cor || MARINHO)};"></div>
          </td>
          <td style="padding-left:8px;font:400 13px Arial, sans-serif;color:${TEXTO};">${esc(cat.rotulo)}</td>
          <td style="font:700 13px Arial, sans-serif;color:${MARINHO};text-align:right;">${esc(cat.valor)}</td>
        </tr>
      </table>
    </td>
  </tr>`;

const linhasCategorias = Array.isArray(c.categorias) ? c.categorias.map(linhaCategoria).join('') : '';

const resumoHtml = (Array.isArray(c.resumoParaOCliente) && c.resumoParaOCliente.length)
  ? `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${FUNDO};border-radius:10px;margin:24px 0;">
      <tr>
        <td style="padding:18px 20px;font:400 13px/1.7 Arial, sans-serif;color:${TEXTO};">
          ${c.resumoParaOCliente.map((linha) => esc(linha)).join('<br>')}
        </td>
      </tr>
    </table>`
  : '';

const html = `
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${FUNDO};padding:32px 0;font-family:Arial, sans-serif;">
  <tr>
    <td align="center">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid ${BORDA};">
        <tr>
          <td style="background:${MARINHO};padding:28px 32px;">
            <div style="font:700 20px Arial, sans-serif;color:#ffffff;">Mapa da Proteção</div>
            <div style="font:400 13px Arial, sans-serif;color:rgba(255,255,255,.75);margin-top:4px;">Preparado para ${esc(c.nome)}</div>
          </td>
        </tr>
        <tr>
          <td style="padding:32px;">
            <p style="font:400 14px/1.6 Arial, sans-serif;color:${TEXTO};margin:0 0 22px;">
              Olá, ${esc(c.nome)}! Segue o resumo do seu Mapa da Proteção, preparado com base nas informações que você compartilhou.
            </p>

            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${FUNDO};border-radius:10px;margin-bottom:24px;">
              <tr>
                <td style="padding:20px 24px;">
                  <div style="font:600 11px Arial, sans-serif;color:${TEXTO_SEC};text-transform:uppercase;letter-spacing:.05em;">Capital total em seguro de vida sugerido</div>
                  <div style="font:700 28px Arial, sans-serif;color:${MARINHO};margin-top:4px;">${fmt(c.totalVida)}</div>
                </td>
              </tr>
            </table>

            <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
              ${linhasResumo}
            </table>

            ${linhasCategorias ? `
            <div style="font:600 13px Arial, sans-serif;color:${MARINHO};margin:24px 0 10px;">Como esse valor se distribui</div>
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
              ${linhasCategorias}
            </table>` : ''}

            ${resumoHtml}

            <p style="font:400 14px/1.6 Arial, sans-serif;color:${TEXTO};margin:22px 0 0;">
              Qualquer dúvida, estou à disposição.
            </p>
          </td>
        </tr>
        <tr>
          <td style="padding:20px 32px;border-top:1px solid ${BORDA};">
            <div style="font:700 13px Arial, sans-serif;color:${MARINHO};">${esc(corretor.nome || 'Setor Norte Seguros')}</div>
            ${corretor.contato ? `<div style="font:400 12px Arial, sans-serif;color:${TEXTO_SEC};margin-top:2px;">${esc(corretor.contato)}</div>` : ''}
          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>`;

return [{
  json: {
    destinatario: b.destinatario,
    assunto: b.assunto || 'Seu Mapa da Proteção',
    corpoHtml: html,
  },
}];
